import { Inject, Injectable, OnModuleInit } from '@nestjs/common';
import type { ClientGrpc } from '@nestjs/microservices';
import { lastValueFrom, Observable } from 'rxjs';

@Injectable()
export class AppleService implements OnModuleInit {
  private bananaGrpc!: BananaGrpc;

  constructor(@Inject('BANANA_GRPC') private readonly client: ClientGrpc) {}

  onModuleInit() {
    this.bananaGrpc = this.client.getService(
      'BananaService',
    ) as unknown as BananaGrpc;
  }

  getHello(): string {
    return 'Tao cua anh Cuong';
  }

  async callBanana(name?: string): Promise<string> {
    // nó sẽ call đến backend banana thông qua gRPC
    const res = await lastValueFrom(this.bananaGrpc.getBanana({ name }));
    return res.message;
  }
}

type GetBananaRequest = {
  name?: string;
};

type GetBananaResponse = {
  message: string;
};

type BananaGrpc = {
  getBanana(data: GetBananaRequest): Observable<GetBananaResponse>;
};

