@Controller()
export class KafkaServerController {
  constructor(private readonly kafkaServerService: KafkaServerService) {}

  // Kafka request/reply (needs reply topic + correlation headers from client)
  @MessagePattern('fruit.ping')
  ping(@Payload() data: unknown) {
    return {
      ok: true,
      service: 'kafka-server',
      data,
      message: this.kafkaServerService.getHello(),
      at: new Date().toISOString(),
    };
  }

  // Kafka fire-and-forget event
  @EventPattern('fruit.events')
  onFruitEvent(@Payload() data: unknown) {
    // Keep it side-effect only; returning is ignored for EventPattern.
    // You can add persistence/logging here later.
    void data;
  }
}

