  const brokers = (process.env.KAFKA_BROKERS ?? 'host.docker.internal:19092')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);

  const app = await NestFactory.createMicroservice<MicroserviceOptions>(
